# module worker_0.py
class Worker0:
    def __init__(self, capacity=32):
        self.capacity = capacity
        self.items = []
        self.closed = False

    def submit(self, item):
        if self.closed:
            raise RuntimeError(closed)
        if len(self.items) >= self.capacity:
            raise OverflowError(full)
        self.items.append(item)

    def take(self):
        if not self.items:
            return None
        return self.items.pop(0)

    def close(self):
        self.closed = True

